// ZIGZAGOpen opens a live [ZIGZAGStream] on a warm-up history, oldest bar
// first, and returns it with its values at the last history bar (outZigZag,
// outTrend and outPivotIdx), the values [Core.ZIGZAG] writes there.
//
// inHigh and inLow are the histories, of one length; the parameters are those
// of [Core.ZIGZAG].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.ZIGZAGLookback] bars, and [BadParam] for a parameter out of range or
// histories of different lengths.
func (c *Core) ZIGZAGOpen(inHigh, inLow []float64, optInSensitivity float64, optInMinTrendLength int) (*ZIGZAGStream, float64, int32, int32, error) {
	if !fitsInt32(optInMinTrendLength) {
		return nil, 0, 0, 0, BadParam
	}
	sp, err := c.zigzagOpenInternal(inHigh, inLow, 0, optInSensitivity, int32(optInMinTrendLength))
	if err != nil {
		return nil, 0, 0, 0, err
	}
	return sp, sp.cur_outZigZag, sp.cur_outTrend, sp.cur_outPivotIdx, nil
}

// ZIGZAGOpenAndFill opens a stream as [Core.ZIGZAGOpen] does and also writes
