	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outZigZag) == 0 || len(outZigZag) < outLen {
		return nil, OutRange{}, BadParam
	}
	if len(outTrend) == 0 || len(outTrend) < outLen {
		return nil, OutRange{}, BadParam
	}
	if len(outPivotIdx) == 0 || len(outPivotIdx) < outLen {
		return nil, OutRange{}, BadParam
	}
